// Die Konfidenz der KI allein reicht als Freigabekriterium nicht: ein Modell ist
// auch dann zuversichtlich, wenn es sich verrechnet hat. Deshalb kommen harte
// Pruefungen dazu, die nichts mit dem Modell zu tun haben - Kontonummer, USt-Satz
// und die Rechnung Netto + USt = Brutto. Erst wenn alles zusammenpasst, darf
// automatisch vorkontiert werden.

const KONFIDENZ_SCHWELLE = 0.8;
const ERLAUBTE_UST = [0, 7, 19];

const raus = [];

for (const eintrag of $input.all()) {
  const v = eintrag.json.message?.content ?? eintrag.json;
  const datei = $('Neue Belege im Ordner suchen').item.json;

  const netto = Number(v.netto ?? 0);
  const ust = Number(v.ust_betrag ?? 0);
  const brutto = Number(v.brutto ?? 0);
  const ustSatz = Number(v.ust_satz ?? -1);
  const konto = String(v.konto_skr03 ?? '').trim();
  const konfidenz = Number(v.konfidenz ?? 0);

  const maengel = [];

  // Kaufmaennische Rundung erlaubt einen Cent Abweichung, mehr nicht.
  if (Math.abs(netto + ust - brutto) > 0.01) {
    maengel.push('Netto plus USt ergibt nicht den Bruttobetrag');
  }
  // SKR03-Konten sind vierstellig. Alles andere ist eine Halluzination.
  if (!/^\d{4}$/.test(konto)) {
    maengel.push('Kontonummer nicht vierstellig');
  }
  if (!ERLAUBTE_UST.includes(ustSatz)) {
    maengel.push('Unplausibler USt-Satz: ' + v.ust_satz);
  }
  // Rechnerische Gegenprobe des Steuerbetrags - deckt vertauschte Netto- und
  // Bruttowerte auf, die der Summentest allein nicht findet.
  if (ERLAUBTE_UST.includes(ustSatz) && ustSatz > 0 && Math.abs(netto * ustSatz / 100 - ust) > 0.02) {
    maengel.push('USt-Betrag passt nicht zum angegebenen Steuersatz');
  }
  if (!v.lieferant || !v.belegdatum) {
    maengel.push('Lieferant oder Belegdatum fehlt');
  }
  if (brutto <= 0) {
    maengel.push('Kein Bruttobetrag erkannt');
  }
  if (!(konfidenz >= KONFIDENZ_SCHWELLE)) {
    maengel.push('Konfidenz ' + konfidenz.toFixed(2) + ' unter der Schwelle ' + KONFIDENZ_SCHWELLE);
  }

  raus.push({
    json: {
      datei_name: datei.name ?? '',
      datei_link: datei.webViewLink ?? '',
      lieferant: v.lieferant ?? null,
      belegdatum: v.belegdatum ?? null,
      belegnummer: v.belegnummer ?? null,
      netto: Number(netto.toFixed(2)),
      ust_satz: ustSatz,
      ust_betrag: Number(ust.toFixed(2)),
      brutto: Number(brutto.toFixed(2)),
      konto_skr03: konto,
      konto_bezeichnung: v.konto_bezeichnung ?? '',
      kostenstelle: String(v.kostenstelle ?? '').trim(),
      buchungstext: String(v.buchungstext ?? '').slice(0, 60),
      konfidenz: Number(konfidenz.toFixed(2)),
      begruendung: v.begruendung ?? '',
      automatisch_kontieren: maengel.length === 0,
      pruefgrund: maengel.join('; '),
    },
  });
}

return raus;

// Aufbau nach DATEV-Buchungsstapel (Format EXTF): Semikolon als Trenner,
// Betraege mit Komma, Belegdatum vierstellig als TTMM. Die Spaltennamen sind
// exakt so gewaehlt, wie der DATEV-Import sie erwartet - wer hier umbenennt,
// bekommt beim Steuerberater eine Fehlermeldung statt eines Stapels.

const SAMMELKREDITOR = '70000';       // Gegenkonto, an das gebucht wird
const STANDARD_KOSTENSTELLE = '';      // leer lassen, wenn ohne KoSt gebucht wird
const TRENNER = ';';

// SKR03 rechnet die Vorsteuer ueber Automatikkonten ab. Steht der Steuersatz
// nicht ohnehin im Konto, muss der BU-Schluessel mit - sonst zieht DATEV keine
// Vorsteuer.
const BU_SCHLUESSEL = { 19: '9', 7: '8', 0: '' };

function datevBetrag(zahl) {
  return Number(zahl).toFixed(2).replace('.', ',');
}

function datevDatum(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  return String(d.getUTCDate()).padStart(2, '0') + String(d.getUTCMonth() + 1).padStart(2, '0');
}

// Semikolon und Anfuehrungszeichen in Buchungstexten wuerden den Stapel
// zerschiessen, daher werden Textfelder gequotet und interne Quotes verdoppelt.
function feld(wert) {
  const s = String(wert ?? '');
  return '"' + s.replace(/"/g, '""') + '"';
}

const SPALTEN = [
  'Umsatz (ohne Soll/Haben-Kz)',
  'Soll/Haben-Kennzeichen',
  'WKZ Umsatz',
  'Konto',
  'Gegenkonto (ohne BU-Schluessel)',
  'BU-Schluessel',
  'Belegdatum',
  'Belegfeld 1',
  'Buchungstext',
  'Kost1 - Kostenstelle',
];

const zeilen = [SPALTEN.map(feld).join(TRENNER)];
const uebersicht = [];

for (const eintrag of $input.all()) {
  const b = eintrag.json;
  zeilen.push([
    feld(datevBetrag(b.brutto)),
    feld('S'),
    feld('EUR'),
    feld(b.konto_skr03),
    feld(SAMMELKREDITOR),
    feld(BU_SCHLUESSEL[b.ust_satz] ?? ''),
    feld(datevDatum(b.belegdatum)),
    feld(String(b.belegnummer ?? '').slice(0, 36)),
    feld(b.buchungstext),
    feld(b.kostenstelle || STANDARD_KOSTENSTELLE),
  ].join(TRENNER));

  uebersicht.push(b.belegdatum + '  ' + String(b.lieferant).padEnd(28).slice(0, 28) + '  ' + datevBetrag(b.brutto).padStart(10) + ' EUR  auf ' + b.konto_skr03 + ' (' + b.konto_bezeichnung + ')');
}

const csv = zeilen.join('\r\n') + '\r\n';
const heute = new Date().toISOString().slice(0, 10);

return [{
  json: {
    dateiname: 'DATEV-Buchungsstapel-' + heute + '.csv',
    anzahl_buchungen: zeilen.length - 1,
    summe_brutto: datevBetrag($input.all().reduce((s, e) => s + Number(e.json.brutto || 0), 0)),
    uebersicht: uebersicht.join('\n'),
    // Base64, weil der naechste Node daraus die eigentliche Datei baut.
    csv_base64: Buffer.from(csv, 'utf8').toString('base64'),
  },
}];
